import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  Image,
  TouchableOpacity,
} from 'react-native';
import {
  Ux4gAppHeader,
  Ux4gDivider,
  Ux4gTag,
  Ux4gLinearProgressBar,
  Ux4gJourneyTimeline,
  Ux4gToast,
  Ux4gToastCategory,
  UX4GColors,
} from 'ux4g-react-native-components';

export const AutoDismissBannerPattern = () => {
  const [bannerVisible, setBannerVisible] = useState(true);

  return (
    <View style={styles.screen}>
      {/* 1. Government App Header */}
      <Ux4gAppHeader
        title=""
        variant="light"
        elevation={0}
        useSafeArea={false}
        horizontalPadding={16}
        leadingSpacing={12}
        backgroundColor={UX4GColors.neutral0}
        borderColor={UX4GColors.neutral200}
        leadingWidgets={[
          <Image key="emblem" source={{ uri: '/national_emblem_logo.svg' }} style={styles.emblemLogo} resizeMode="contain" />,
          <View key="divider" style={styles.headerDivider} />,
          <Image key="union" source={{ uri: '/Union.svg' }} style={styles.unionLogo} resizeMode="contain" />,
        ]}
        actions={[
          {
            customWidget: (
              <View style={styles.menuBtn}>
                <Text style={styles.menuIcon}>☰</Text>
              </View>
            ),
          },
        ]}
      />
      <Ux4gDivider color={UX4GColors.neutral200} />

      {/* 2. Scrollable Body */}
      <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: 16, paddingBottom: bannerVisible ? 100 : 20 }}>
        {/* Back Link */}
        <TouchableOpacity style={styles.backRow} onPress={() => {}}>
          <Text style={styles.backArrow}>←</Text>
          <Text style={styles.backText}>Back</Text>
        </TouchableOpacity>

        <View style={{ height: 16 }} />

        {/* Card 1: Application Status */}
        <View style={styles.card}>
          <View style={styles.cardHeaderRow}>
            <Text style={styles.cardTitle}>Income Certificate</Text>
            <Ux4gTag
              text="Under Review"
              shape="rectangular"
              style="tonal"
              size="m"
            />
          </View>

          <Text style={styles.cardSubtitle}>Application ID · INC-2026-MH-04127</Text>

          <View style={{ height: 14 }} />

          <Ux4gLinearProgressBar
            value={0.38}
            label="8 days left"
            height={6}
            shape="rounded"
            gradientColors={[UX4GColors.secondary300, UX4GColors.secondary600]}
          />
        </View>

        <View style={{ height: 16 }} />

        {/* Card 2: Application Journey Timeline */}
        <View style={styles.card}>
          <Ux4gJourneyTimeline
            activeColor={UX4GColors.primary}
            indicatorSize={18}
            lineWidth={2}
            header={{
              title: 'Application journey',
              description: 'Every step from submission to issuance',
            }}
            steps={[
              {
                state: 'completed',
                date: '07 Apr 2026, 10:24 AM',
                title: 'Application Submitted',
              },
              {
                state: 'completed',
                date: '10 Apr 2026, 02:15 PM',
                title: 'Documents Verified',
              },
              {
                state: 'current',
                date: '11 Apr 2026 (Est)',
                title: 'Under Review',
                dateColor: UX4GColors.primary,
                cardColor: '#F3F0FF',
                cardBorderColor: UX4GColors.primary,
              },
              {
                state: 'upcoming',
                date: '22 Apr 2026 (Est)',
                title: 'Decision',
                status: {
                  text: '2 days remaining',
                  dotColor: UX4GColors.secondary,
                  badgeText: 'Pending',
                  badgeColor: 'transparent',
                  badgeTextColor: UX4GColors.secondary,
                },
              },
            ]}
          />
        </View>

        <View style={{ height: 32 }} />

        {/* Footer */}
        <View style={styles.footer}>
          <Text style={styles.poweredByText}>Powered by -</Text>
          <Image source={{ uri: '/Digital_India_logo.svg' }} style={styles.digitalIndiaLogo} resizeMode="contain" />
        </View>
      </ScrollView>

      {/* 3. Floating Bottom Toast Banner */}
      {bannerVisible && (
        <View style={styles.floatingToastContainer}>
          <Ux4gToast
            category="info"
            title="Application Under Review"
            subtitle="Your application moved to Under Review. This banner auto-dismisses in 5 seconds."
            showCloseButton={false}
            layout="stacked"
          />
          <Text style={styles.toastTimestamp}>12:30PM</Text>
        </View>
      )}
    </View>
  );
};

