import {
  SafeAreaView,
  ScrollView,
  View,
  Text,
  TouchableOpacity,
  Image,
  StyleSheet,
} from 'react-native';
import {
  Ux4gAppHeader,
  Ux4gCard,
  Ux4gDivider,
  Ux4gDividerOrientation,
  Ux4gSearchField,
  UX4GColors,
} from 'ux4g-react-native-components';

const CATEGORIES = [
  'Application Issues',
  'Documents and Uploads',
  'Payments and Fees',
  'Account and Profile',
  'Technical Issues',
];

/// Card Style variant — help centre inside a white card on purple background.
export const HelpCentreCardScreen = ({ isDark = false }: { isDark?: boolean }) => {
  const [search, setSearch] = useState('');
  const screenBg = isDark ? UX4GColors.primary800 : UX4GColors.primary100;
  const cardBg = isDark ? '#1A1A1A' : '#FFFFFF';
  const titleColor = isDark ? '#FFFFFF' : '#111827';
  const subtleTextColor = isDark ? '#9CA3AF' : '#4B5563';
  const borderColor = isDark ? UX4GColors.neutral700 : '#E5E7EB';

  return (
    <SafeAreaView style={[styles.safeArea, { backgroundColor: screenBg }]}>
      {/* App Header */}
      <Ux4gAppHeader
        elevation={2}
        variant="light"
        title=""
        leadingSpacing={8}
        leadingWidgets={[
          <NationalEmblemLogo key="emblem" isDark={isDark} height={40} />,
          <View key="divider" style={styles.headerDividerWrapper}>
            <Ux4gDivider
              orientation={Ux4gDividerOrientation.vertical}
              color="#D1D5DB"
            />
          </View>,
          <UnionLogo
            key="union"
            size={32}
            color={isDark ? UX4GColors.primary300 : UX4GColors.primary600}
          />,
        ]}
      actions={[
        {
          customWidget: (
            <TouchableOpacity
              key="menu"
              style={styles.menuBtn}
              onPress={() => {}}
            >
              <Text style={styles.menuIcon}>☰</Text>
            </TouchableOpacity>
          ),
        },
      ]}
      />

      {/* White Card Content */}
      <ScrollView
        style={styles.scroll}
        contentContainerStyle={styles.scrollContent}
      >
        <Ux4gCard
          backgroundColor={cardBg}
          cornerRadius={16}
          style={styles.card}
        >
          <Text style={[styles.title, { color: titleColor }]}>Help Centre</Text>
          <Text style={[styles.subtitle, { color: subtleTextColor }]}>
            Find answers to common questions or contact our support team.
          </Text>

          {/* Search Field */}
          <View style={styles.searchWrapper}>
            <Ux4gSearchField
              value={search}
              onValueChange={setSearch}
              placeholder="Search for..."
              variant="searchWithSubmit"
              showVoiceIcon
              buttonStyle="filled"
              onSubmitClick={(val) => console.log('Searching for:', val)}
            />
          </View>

          {/* Categories Section */}
          <Text style={[styles.sectionTitle, { color: subtleTextColor }]}>
            Browse by category
          </Text>

          <Ux4gCard
            backgroundColor={cardBg}
            cornerRadius={12}
            borderColor={borderColor}
            borderWidth={1}
            style={styles.categoryCard}
          >
            {CATEGORIES.map((category, index) => (
              <View key={category}>
                <TouchableOpacity
                  style={styles.categoryItem}
                  onPress={() => console.log('Selected:', category)}
                  activeOpacity={0.7}
                >
                  <Text style={[styles.categoryText, { color: titleColor }]}>
                    {category}
                  </Text>
                  <ChevronRightIcon color="#4B5563" size={20} />
                </TouchableOpacity>
                {index < CATEGORIES.length - 1 && (
                  <Ux4gDivider color={borderColor} />
                )}
              </View>
            ))}
          </Ux4gCard>
        </Ux4gCard>
      </ScrollView>

      {/* Powered by Digital India */}
      <View style={styles.footerRow}>
        <Text
          style={[
            styles.footerText,
            { color: isDark ? UX4GColors.neutral400 : '#6B7280' },
          ]}
        >
          Powered by -
        </Text>
        <Image
          source={{ uri: '/digital_india_logo.png' }}
          style={styles.digitalIndiaLogo}
          resizeMode="contain"
        />
      </View>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  menuBtn: {
    width: 36,
    height: 36,
    borderRadius: 8,
    borderWidth: 1.5,
    borderColor: UX4GColors.primary200,
    backgroundColor: UX4GColors.neutral0,
    justifyContent: 'center',
    alignItems: 'center',
  },
  menuIcon: {
    fontSize: 18,
    color: UX4GColors.primary,
  },
  safeArea: {
    flex: 1,
  },
  headerDividerWrapper: {
    height: 32,
    justifyContent: 'center',
  },
  scroll: {
    flex: 1,
  },
  scrollContent: {
    padding: 16,
  },
  card: {
    padding: 16,
    borderRadius: 16,
  },
  title: {
    fontSize: 22,
    fontWeight: '800',
    marginBottom: 8,
  },
  subtitle: {
    fontSize: 14,
    marginBottom: 20,
    lineHeight: 20,
  },
  searchWrapper: {
    marginBottom: 20,
  },
  sectionTitle: {
    fontSize: 14,
    fontWeight: '600',
    marginBottom: 8,
  },
  categoryCard: {
    borderRadius: 12,
    overflow: 'hidden',
    marginBottom: 16,
  },
  categoryItem: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingVertical: 14,
    paddingHorizontal: 16,
  },
  categoryText: {
    fontSize: 14,
    fontWeight: '600',
  },
  footerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 4,
    paddingBottom: 12,
  },
  footerText: {
    fontSize: 11,
  },
  digitalIndiaLogo: {
    height: 20,
    width: 60,
  },
});
